#!/usr/bin/env python3
import argparse,json,shutil,html
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('directory');a=p.parse_args();out=Path(a.directory);results=json.loads((out/'results.json').read_text());refs=out/'references';refs.mkdir(exist_ok=True)
for name in ['chatgrab-header-approved.png','workspace-metal-atlas.png','workspace-reference.png']:
 shutil.copy(Path('public/images')/name,refs/name)
cards=[]
for width in [1440,390,320]:
 for page in ['capture','workspace','guide','settings']:
  name=f'{page}-{width}.png'
  if (out/name).exists():cards.append(f'<article data-width="{width}"><h3>{page.title()} · {width}px</h3><a href="{name}"><img src="{name}" alt="{page} at {width} pixels"></a><p><a href="{name}">Open full-size screenshot</a></p></article>')
body=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ChatGrab secure acceptance review</title><style>body{{font:16px/1.6 system-ui;margin:0;background:#eef3fa;color:#122d4e}}main{{max-width:1400px;margin:auto;padding:25px}}h1{{line-height:1.1}}a{{color:#1751bd}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:20px}}article,section{{background:white;border:1px solid #bdcee4;border-radius:16px;padding:20px;margin:20px 0}}img{{max-width:100%;height:auto}}article img{{max-height:720px;object-fit:contain;object-position:top}}.refs img{{max-height:300px;object-fit:contain}}button{{padding:10px 20px;font:inherit;margin:5px;background:white;border:1px solid #6690c8;border-radius:10px}}[hidden]{{display:none!important}}</style><main><h1>ChatGrab browser acceptance review</h1><p>Tested origin: {html.escape(results['base'])}. These are Codex-executed observations over synthetic data. Independent reviewer acceptance is still yours.</p><p><a href="results.json">Checks and browser metadata</a> · <a href="asset-proof.json">Delivered artwork hashes</a> · <a href="trace-sanitized.zip">Download scrubbed Playwright trace</a> · <a href="trace-sanitized.zip.redaction.json">Redaction check</a></p><section><h2>Inspect without a paid browser service</h2><p>With Playwright installed locally, run <code>npx playwright show-trace trace-sanitized.zip</code>. It opens a local viewer; do not supply credentials or upload your private browser profile. The scrubbed recording includes actual clicks, DOM snapshots and requests. Full-size screenshots are separate; redundant filmstrip frames are omitted to keep the package smaller. Inspecting the recording is different from independently rerunning the tests.</p><p>For a fresh run, use your own Vercel login/development OIDC session and the repository's <code>npm run test:replay</code> instructions. No protection settings need to change.</p></section><section class="refs"><h2>Specific reference artwork</h2><div class="grid"><div><h3>Repository-selected approved header</h3><img src="references/chatgrab-header-approved.png" alt="Approved ChatGrab header logo"><p>Compare this intact graphic with the top navigation in each screenshot.</p></div><div><h3>Existing metallic illustration atlas</h3><img src="references/workspace-metal-atlas.png" alt="Metallic ChatGrab artwork atlas"><p>The six workspace cards use independent cells from this same delivered file. Hash equality proves source bytes, not subjective approval of layout.</p></div></div><details><summary>Earlier layout reference — historical, not a pixel-perfect current baseline</summary><img src="references/workspace-reference.png" alt="Earlier pastel workspace layout"><p>The later metallic artwork, header and persistent sidebar differ from this old composite. This review preserves the current selected assets and makes no new claim that every pixel matches the historical mockup.</p></details></section><h2>Desktop and phone observations</h2><div><button data-show="all">All widths</button><button data-show="1440">Desktop</button><button data-show="390">Phone 390</button><button data-show="320">Phone 320</button></div><div class="grid">{''.join(cards)}</div><section><h2>Remaining external gates</h2><p>Physical Android/PWA, a genuine native export, authenticated fresh-chat restoration, native plugin installation/context grant and actual worker ACK are not established by this recording. Remote public-share capture can still return metadata-only; the reviewed manual route is tested. Live payments remain disabled.</p></section></main><script>document.querySelectorAll('button[data-show]').forEach(b=>b.onclick=()=>document.querySelectorAll('article[data-width]').forEach(a=>a.hidden=b.dataset.show!=='all'&&a.dataset.width!==b.dataset.show));</script></html>'''
(out/'review.html').write_text(body)
print('Review gallery built with',len(cards),'viewport screenshots')
